    println!("{indent}{} {:?}{}{}", node.kind(), truncated, named, is_error);
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) { dump(child, src, depth + 1); }
}
fn main() {
    let samples = vec![
        // 0: class attributes Abstract = false
        "classdef (Abstract = false) Foo
end
",
