    properties (Constant, Abstract)
        X
    end
end
",
        // 5: dependent with default
        "classdef DepClass
    properties (Dependent)
        Y = 5
    end
end
",
        // 6: handle class
        "classdef (Abstract = true) HClass < handle
    properties (SetObservable, GetObservable, AbortSet)
        Data
    end
end
",
        // 7: method with x * x'  (MHERM)
        "classdef Foo
    methods
        function z = compute(obj, x)
            z = x * x';
        end
    end
end
",
        // 8: zeros(numel(x)) (MNUML)
        "y = zeros(numel(x));
",
        // 9: events block
        "classdef Foo
    events
        ColorChanged
    end
end
",
        // 10: method named ans
        "classdef Foo
    methods
        function ans = calc(obj)
            ans = 1;
        end
    end
end
",
        // 11: property called as function (MCCPE)
        "classdef Foo
    properties
        Color
    end
    methods
        function go(obj)
            Color;
        end
    end
end
",
        // 12: zeros(3,3) must not fire
        "y = zeros(3, 3);
",
        // 13: parenthesized x*x'
        "classdef Foo
    methods
        function z = compute(obj, x)
            z = (x * x');
        end
    end
end
",
        // 14: dependent with get method and no default
        "classdef DepClass
    properties (Dependent, GetAccess = public)
        Y
    end
    methods
        function val = get.Y(obj)
            val = 1;
        end
    end
end
",
        // 15: events with attributes + GetObservable on event?  just event with name
        "classdef Foo
    properties (Constant)
        X
    end
end
",
    ];
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    for (i, s) in samples.iter().enumerate() {
        let tree = parser.parse(s, None).unwrap();
        println!("===== {i}: {s:?} =====");
        dump(tree.root_node(), s, 0);
        println!();
    }
}
